"""
Repro tests for W2001 with AWS::Include inside RestApi Body
"""
import os
import json
import pytest

from cfnlint import Template
from cfnlint.rules.parameters.Used import Used


def run_rule(template_dict):
    cfn = Template("-/tmp/template.yaml", template_dict, regions=["us-east-1"])
    rule = Used()
    return list(rule.match(cfn))


@pytest.fixture
def tmp_openapi_file(tmp_path):
    def write_content(content_dict):
        p = tmp_path / "openapi.json"
        p.write_text(json.dumps(content_dict))
        return str(p)
    return write_content


def make_restapi_with_include(location):
    return {
        "AWSTemplateFormatVersion": "2010-09-09",
        "Parameters": {
            "A": {"Type": "String"},
            "B": {"Type": "String"},
        },
        "Resources": {
            "Api": {
                "Type": "AWS::ApiGateway::RestApi",
                "Properties": {
                    "Body": {
                        "Fn::Transform": {
                            "Name": "AWS::Include",
                            "Parameters": {"Location": location},
                        }
                    }
                },
            }
        },
    }


def test_positive_include_usage(tmp_openapi_file):
    # Included file references A and B via Ref/Sub
    location = tmp_openapi_file({
        "x-cfn": {"Ref": "A"},
        "x-sub": {"Fn::Sub": "${B}"},
    })
    t = make_restapi_with_include(location)
    matches = run_rule(t)
    # No W2001 for A or B
    assert all(m.rule.id != "W2001" for m in matches), f"Unexpected W2001: {matches}"


def test_unused_parameter_with_include(tmp_openapi_file):
    # Include references only A; template defines A,B,C where C unused
    location = tmp_openapi_file({
        "x-cfn": {"Ref": "A"},
    })
    t = make_restapi_with_include(location)
    # add C
    t["Parameters"]["C"] = {"Type": "String"}
    matches = run_rule(t)
    # Should flag C unused
    assert any(
        m.rule.id == "W2001" and "C" in m.message for m in matches
    ), f"Expected C unused, got: {matches}"


def test_no_include_baseline():
    t = {
        "AWSTemplateFormatVersion": "2010-09-09",
        "Parameters": {"D": {"Type": "String"}, "E": {"Type": "String"}},
        "Resources": {
            "Anything": {"Type": "AWS::S3::Bucket"}
        },
    }
    matches = run_rule(t)
    assert any(
        m.rule.id == "W2001" and "E" in m.message for m in matches
    ), f"Baseline W2001 unchanged: {matches}"


def test_remote_include(tmp_openapi_file):
    # Remote include: do not parse, W2001 should flag F
    location = "https://example.com/openapi.json"
    t = {
        "AWSTemplateFormatVersion": "2010-09-09",
        "Parameters": {"F": {"Type": "String"}},
        "Resources": {
            "Api": {
                "Type": "AWS::ApiGateway::RestApi",
                "Properties": {
                    "Body": {
                        "Fn::Transform": {
                            "Name": "AWS::Include",
                            "Parameters": {"Location": location},
                        }
                    }
                },
            }
        },
    }
    matches = run_rule(t)
    assert any(
        m.rule.id == "W2001" and "F" in m.message for m in matches
    ), f"Remote include should not mark F used: {matches}"


def test_non_apigateway_transform(tmp_openapi_file):
    # Using Include under non-ApiGateway resource should not affect W2001
    location = tmp_openapi_file({"x": {"Ref": "A"}})
    t = {
        "AWSTemplateFormatVersion": "2010-09-09",
        "Parameters": {"A": {"Type": "String"}, "B": {"Type": "String"}},
        "Resources": {
            "Other": {
                "Type": "AWS::S3::Bucket",
                "Properties": {
                    "BucketName": {
                        "Fn::Transform": {
                            "Name": "AWS::Include",
                            "Parameters": {"Location": location},
                        }
                    }
                },
            }
        },
    }
    matches = run_rule(t)
    # B unused should still be flagged
    assert any(
        m.rule.id == "W2001" and "B" in m.message for m in matches
    ), f"Non-ApiGateway Include should not mark B used: {matches}"

