subs = []
for subtree in subtrees:
    if isinstance(subtree[-1], list):
        subs.extend(cfn.get_sub_parameters(subtree[-1][0]))
    elif isinstance(subtree[-1], str):
        subs.extend(cfn.get_sub_parameters(subtree[-1]))

# Augment used parameters by parsing local include referenced by RestApi Body
try:
    parameters_defined = set(cfn.template.get("Parameters", {}).keys())
    # Only for AWS::ApiGateway::RestApi Body Fn::Transform Name: AWS::Include
    for _, resource in cfn.get_resources("AWS::ApiGateway::RestApi").items():
        props = resource.get("Properties", {})
        body = props.get("Body")
        if not isinstance(body, dict):
            continue
        if list(body.keys()) != ["Fn::Transform"]:
            continue
        transform = body.get("Fn::Transform", {})
        if not (
            isinstance(transform, dict)
            and transform.get("Name") == "AWS::Include"
        ):
            continue
        loc = (
            transform.get("Parameters", {}) if isinstance(transform.get("Parameters"), dict) else {}
        ).get("Location")
        if not isinstance(loc, str):
            continue
        # local file only (no scheme)
        if "://" in loc:
            continue
        # Resolve relative paths based on template filename
        resolved = loc
        try:
            if cfn.filename and not os.path.isabs(resolved):
                resolved = os.path.join(os.path.dirname(cfn.filename), resolved)
        except Exception:
            pass
        if not os.path.isfile(resolved):
            continue
        # Parse included content (JSON or YAML). Favor JSON, fallback to YAML loader from decode
        included_obj = None
        try:
            with open(resolved, "r", encoding="utf-8") as f:
                text = f.read()
            try:
                included_obj = json.loads(text)
            except Exception:
                # lazy import to avoid heavy deps
                from cfnlint.decode import cfn_yaml

                included_obj = cfn_yaml.loads(text)
        except Exception:
            included_obj = None
        if not isinstance(included_obj, (dict, list)):
            continue
        # Scan included content for Refs and Fn::Sub
        # We can reuse Template.search_deep_keys via a temporary Template-like wrapper by using cfn methods
        # Create a minimal Template to use helpers safely
        temp_cfn = Template(None, {"Included": included_obj}, regions=cfn.regions)
        inc_refs = [p[-1] for p in temp_cfn.search_deep_keys("Ref")]
        inc_subs = []
        for p in temp_cfn.search_deep_keys("Fn::Sub"):
            if isinstance(p[-1], list):
                inc_subs.extend(temp_cfn.get_sub_parameters(p[-1][0]))
            elif isinstance(p[-1], str):
                inc_subs.extend(temp_cfn.get_sub_parameters(p[-1]))
        # Only consider parameters that exist in the template and are not pseudo params
        used_in_includes = set()
        for name in inc_refs + inc_subs:
            if not isinstance(name, str):
                continue
            if name.startswith("AWS::"):
                continue
            if name in parameters_defined:
                used_in_includes.add(name)
        # Merge into existing refs/subs
        for name in used_in_includes:
            if name not in refs:
                refs.append(name)
except Exception:
    # best-effort; keep default behavior on errors
    pass

for paramname in cfn.template.get("Parameters", {}).keys():
    if paramname not in refs:
        if paramname not in subs:
            message = "Parameter {0} not used."
            matches.append(
                RuleMatch(["Parameters", paramname], message.format(paramname))
            )

return matches
